         // module will refresh once data is available. For now, show
         // the iframe and let the writer click "Open ↗" for the live
         // markdown preview.
         store.embedProvider = "iframe";
         void mod;
       } catch {
         store.embedProvider = null;
       } finally {
         store.embedLoading = false;
       }
     });

     const closeEmbed = $(() => {
