       const text =
         from !== to
           ? editor.state.doc.textBetween(from, to, "\n\n")
           : editor.getText();
       if (!text.trim()) return;
       await speak({
         id: MANUSCRIPT_READING_ID,
         text,
         client: clientSig.value ?? null,
         signedIn: Boolean(auth.value.user),
       });
     });

