                                         fontFamily: "var(--font-typewriter)",
                                         borderRadius: "2px",
                                       }}
                                     >
                                       <option value="">
                                         {selectedProvider
                                           ? `Use automatic provider (${selectedProvider.name})`
                                           : "No compatible provider"}
