                                         Temperature
                                       </label>
                                       <input
                                         type="number"
                                         min={0}
                                         max={1}
                                         step={0.1}
                                         value={
                                           store.settings.perFeature[feature]
                                             ?.temperature ?? ""
                                         }
                                         onInput$={(e) => {
                                           const temp = Number(
                                             (e.target as HTMLInputElement)
                                               .value,
                                           );
                                           const existing =
                                             store.settings.perFeature[feature];
                                           setFeatureOverride(feature, {
                                             providerId:
                                               existing?.providerId ??
                                               store.settings
                                                 .defaultProviderId ??
                                               "",
                                             model: existing?.model,
                                             temperature:
                                               temp >= 0 && temp <= 1
                                                 ? temp
                                                 : undefined,
                                             maxTokens: existing?.maxTokens,
                                           });
                                         }}
