                                         Max tokens
                                       </label>
                                       <input
                                         type="number"
                                         min={50}
                                         max={4000}
                                         step={10}
                                         value={
                                           store.settings.perFeature[feature]
                                             ?.maxTokens ?? ""
                                         }
                                         onInput$={(e) => {
                                           const tokens = Number(
                                             (e.target as HTMLInputElement)
                                               .value,
                                           );
                                           const existing =
                                             store.settings.perFeature[feature];
                                           setFeatureOverride(feature, {
                                             providerId:
                                               existing?.providerId ??
                                               store.settings
                                                 .defaultProviderId ??
                                               "",
