                       class="w-24 text-sm px-2 py-1.5 border border-[var(--color-paper-3)] bg-[var(--color-paper)] focus:border-[var(--color-vermilion)] focus:outline-none"
                       style={{
                         fontFamily: "var(--font-typewriter)",
                         borderRadius: "2px",
