             {/* ── Writer handle (public identity) ── */}
             {auth.value.provider === "convex" && store.handleLoaded && (
               <section class="folio p-5 border border-[var(--color-paper-3)]">
                 <h2
                   class="text-base font-semibold mb-1"
                   style={{ fontFamily: "var(--font-display)" }}
