                           for="writer-avatar"
                         >
                           Profile picture
                         </label>
                         <div class="flex flex-wrap items-center gap-2">
                           <input
                             id="writer-avatar"
                             type="file"
                             accept="image/*"
                             disabled={store.profileAvatarBusy}
                             onChange$={(e) => {
