                               onClick$={handleAvatarClear}
                               disabled={store.profileAvatarBusy}
                               class="text-[0.7rem] tracking-[0.12em] uppercase text-[var(--color-vermilion)] hover:underline disabled:opacity-50"
                               style={{ fontFamily: "var(--font-typewriter)" }}
