 {"title": "<title>", "author": "<author if known>", "year": "<year if known>", "date": "<publication date if known>", "url": "<url if known>", "doi": "<doi if known>", "publisher": "<publisher if known>", "formatted": "<full ${req.style} citation>"}`;

