export interface TargetExtractRequest {
  draftText: string;
  existingSources: string[];
  maxTargets?: number;
  instructions?: string;
}

/**
 * The agentic front of auto-research. The model reads the draft and decides
 * exactly which passages need a source (a quote to attribute, a film, a
 * statistic, a claim), and for each returns a precise search query. The
 * background watcher then resolves each target one at a time through the
 * configured research provider.
 */
export async function runClientResearchExtract(
  req: TargetExtractRequest,
  settings: AiSettings,
): Promise<{ targets: ResearchTarget[]; provider: string } | null> {
  const resolved = resolveFeatureConfig(settings, "research-extract");
  if (!resolved) return null;

  const model = await createModel(resolved.provider, resolved.model);
  if (!model) return null;

  const maxTargets = Math.max(1, Math.min(6, req.maxTargets ?? DEFAULT_TARGETS_PER_PASS));

  try {
    const text = await generateTrackedText({
      feature: "research-extract",
      resolved,
      model,
      system: buildResearchExtractSystemPrompt(),
      prompt: buildResearchExtractUserPrompt({
        draftText: req.draftText,
        existingSources: req.existingSources,
        maxTargets,
        instructions: req.instructions,
      }),
      spanName: "research_extract",
      evalSignals: {
        twyne_draft_chars: req.draftText.length,
        twyne_existing_sources_count: req.existingSources.length,
        twyne_expected_format: "json_research_targets",
      },
    });

    const targets = parseResearchTargets(text);
    if (targets.length === 0) return null;
    return { targets, provider: resolved.provider.type };
  } catch (err) {
    reportApplicationDiagnostic("twyne:ai-client:research-extract", err);
    return null;
  }
}

export interface ClientResearchSource {
  title: string;
  url: string;
  snippet: string;
  author?: string;
  publisher?: string;
  date?: string;
  why?: string;
}

export async function runClientResearchWebSearch(
  req: {
    query: string;
    context?: string;
    maxResults: number;
    instructions?: string;
  },
  settings: AiSettings,
): Promise<{ results: ClientResearchSource[]; provider: string } | null> {
  const resolved = resolveFeatureConfig(settings, "research-web-search");

/**
 * Background agents — the Apparatus runs in the background, watching the
 * draft and building an automatic bibliography without the writer having to
 * ask. The model is intentionally simple:
 *
 *   1. Watch the active folio for content changes (debounced).
 *   2. Hand the draft to the writer's AI model, which decides what genuinely
 *      needs a source: a quote to attribute, a named film or book, a
 *      statistic, a checkable claim. Each becomes a ResearchTarget carrying
 *      its own precise search query.
 *   3. Skip targets whose passage already has a saved source or was
 *      researched recently (dedupe), cap the pass at a few targets.
 *   4. Resolve each target through the configured research provider, one
 *      query at a time, and merge the best hit into the bibliography with
 *      `provenance: "background"` so the panel can tell who found them.
 *   5. Emit `twyne:background-research` and `twyne:background-sources` so
 *      the UI can show what is happening.
 *
 * The Convex client, a research provider, and an AI model are all required.
 * Without the record the watcher is a no-op — the writer will still see
 * their manually-saved sources.
 */

