display.text:
import {
  component$,
  useStore,
  useStylesScoped$,
  useVisibleTask$,
  $,
} from "@builder.io/qwik";
import { Link, type DocumentHead } from "@builder.io/qwik-city";
import type { DetectedCitation, Folio, ProjectBrief } from "../../types";
import { detectCitations } from "../../utils/citations";
import {
  type BibEntry,
  type CitationStyle,
  loadBibliography,
  deleteBibEntry,
  formatCitation,
  buildBibEntryFromFormattedCitation,
  mergeBibEntry,
} from "../../utils/bibliography";
import {
  loadApparatusSettingsFromIdb,
  loadActiveFolioIdFromIdb,
  loadFoliosFromIdb,
  loadFolioContentFromIdb,
  saveApparatusSettingsToIdb,
} from "../../utils/idb";
import { snapshot as researchSnapshot } from "../../utils/background-research";
import { targetKindLabel } from "../../utils/research-targets";
import {
  hasConfiguredAiProvider,
  runClientCitationFormat,
  runClientSourceSummarize,
  runClientMissingSourceDetect,
} from "../../utils/ai-client";
import { loadAiSettingsFromIdb } from "../../utils/idb";
import type { AiSettings, SourceSummarizeResult } from "../../types";

interface ApparatusStore {
  bibliography: BibEntry[];
  citations: DetectedCitation[];
  style: CitationStyle;
  activeFolio: Folio | null;
  brief: ProjectBrief | null;
  embedUrl: string | null;
  embedTitle: string;
  embedMarkdown: string | null;
  embedProvider: string | null;
  embedLoading: boolean;
  research: {
    status: "idle" | "running" | "saving" | "error";
    lastQuery: string;
    lastQueryAt: number;
    savedThisSession: number;
    lastTickAt: number;
    provider?: string;
    error?: string;
  };
  showResearchLog: boolean;
  /* ── AI-enhanced apparatus ─────────────────────────────────── */
  aiSettings: AiSettings | null;
  aiLoading: Record<string, boolean>;
  aiSummaries: Record<string, SourceSummarizeResult>;
  aiEnhanceCitations: boolean;
  flagMissingSources: boolean;
  /** Citation ids that have been added to the bibliography. */
  addedCitationIds: Record<string, boolean>;
  aiMissingSources: {
    claims: Array<{
      claim: string;
      reason: string;
      suggestedQuery: string;
    }>;
    provider: string;
  } | null;
  aiScanningMissing: boolean;
}

const STYLE_OPTIONS: ReadonlyArray<{ value: CitationStyle; label: string }> = [
  { value: "mla", label: "MLA" },
  { value: "apa", label: "APA" },
  { value: "chicago", label: "Chicago" },
];

export default component$(() => {
  const store = useStore<ApparatusStore>({
    bibliography: [],
    citations: [],
    style: "mla",
    activeFolio: null,
    brief: null,
    embedUrl: null,
    embedTitle: "",
    embedMarkdown: null,
    embedProvider: null,
    embedLoading: false,
    research: {
      status: "idle",
      lastQuery: "",
      lastQueryAt: 0,
      savedThisSession: 0,
      lastTickAt: 0,
    },
    showResearchLog: false,
    aiSettings: null,
    aiLoading: {},
    aiSummaries: {},
    aiEnhanceCitations: false,
    flagMissingSources: false,
    addedCitationIds: {},
    aiMissingSources: null,
    aiScanningMissing: false,
  });

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(async () => {
    const apparatusSettings = await loadApparatusSettingsFromIdb();
    store.style = apparatusSettings.defaultCitationStyle;
    store.aiEnhanceCitations = apparatusSettings.aiEnhanceCitations;
    store.flagMissingSources = apparatusSettings.flagMissingSources;
    store.bibliography = await loadBibliography();
    const folios = await loadFoliosFromIdb();
    const activeFolioId = await loadActiveFolioIdFromIdb();
    store.activeFolio =
      folios.find((folio) => folio.id === activeFolioId) ?? folios[0] ?? null;
    if (store.activeFolio) {
      const html = await loadFolioContentFromIdb(store.activeFolio.id);
      const text = html.replace(/<[^>]+>/g, " ");
      store.citations = detectCitations(text);
    }
    store.aiSettings = await loadAiSettingsFromIdb();
    if (
      store.aiEnhanceCitations &&
      hasConfiguredAiProvider(store.aiSettings) &&
      store.aiSettings &&
      store.activeFolio
    ) {
      for (const citation of store.citations) {
        const entryId = `ai-fmt-${store.activeFolio.id}-${citation.id}`.replace(
          /[^a-zA-Z0-9_-]/g,
          "-",
        );
        if (store.bibliography.some((entry) => entry.id === entryId)) continue;
        const result = await runClientCitationFormat(
          {
            rawText: citation.text,
            style: store.style,
            context: store.activeFolio.name,
          },
          store.aiSettings,
        );
        if (!result) continue;
        const all = await mergeBibEntry(
          buildBibEntryFromFormattedCitation(
            citation,
            result,
            store.activeFolio.id,
          ),
        );
        store.bibliography = all;
      }
    }
  });

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(() => {
    const pull = () => {
      const s = researchSnapshot();
      store.research = {
        status: s.status as ApparatusStore["research"]["status"],
        lastQuery: s.lastQuery,
        lastQueryAt: s.lastQueryAt,
        savedThisSession: s.savedThisSession,
        lastTickAt: s.lastTickAt,
        provider: s.provider,
        error: s.error,
      };
    };
    const onSources = () => {
      void loadBibliography().then((all) => {
        store.bibliography = all;
      });
    };
    pull();
    window.addEventListener("twyne:background-research", pull);
    window.addEventListener("twyne:background-sources", onSources);
    return () => {
      window.removeEventListener("twyne:background-research", pull);
      window.removeEventListener("twyne:background-sources", onSources);
    };
  });

  useStylesScoped$(`
    .style-toggle {
      display: inline-flex; border: 1px solid var(--color-paper-3);
      border-radius: 2px; overflow: hidden;
    }
    .style-toggle button {
      padding: 0.2rem 0.6rem;
      font-family: var(--font-typewriter);
      font-size: 0.7rem;
      letter-spacing: 0.1em;
      background: var(--color-paper-soft);
      color: var(--color-ink-light);
    }
    .style-toggle button[aria-pressed="true"] {
      background: var(--color-vermilion);
      color: var(--color-paper);
    }
    .card {
      border: 1px solid var(--color-paper-3);
      background: var(--color-paper);
      border-radius: 4px;
    }
    .row {
      padding: 0.85rem 1rem;
      border-bottom: 1px dashed var(--color-paper-3);
    }
    .row:last-child { border-bottom: none; }
    .empty {
      padding: 2rem 1rem;
      text-align: center;
      color: var(--color-ink-muted);
    }
    .agent-pill {
      display: inline-block;
      padding: 0.1rem 0.45rem;
      border: 1px solid var(--color-mustard);
      color: var(--color-mustard);
      border-radius: 2px;
      font-family: var(--font-typewriter);
      font-size: 0.6rem;
      letter-spacing: 0.1em;
      text-transform: uppercase;
    }
    .cited-pill {
      display: inline-block;
      padding: 0.1rem 0.45rem;
      border: 1px solid var(--color-accent-green);
      color: var(--color-accent-green);
      border-radius: 2px;
      font-family: var(--font-typewriter);
      font-size: 0.6rem;
      letter-spacing: 0.1em;
      text-transform: uppercase;
    }
    .status-dot {
      display: inline-block; width: 0.5rem; height: 0.5rem; border-radius: 999px;
    }
  `);

  const setStyle = $(async (s: CitationStyle) => {
    store.style = s;
    const current = await loadApparatusSettingsFromIdb();
    await saveApparatusSettingsToIdb({
      ...current,
      defaultCitationStyle: s,
    });
  });

  const dropEntry = $(async (id: string) => {
    const all = await deleteBibEntry(id);
    store.bibliography = all;
  });

  const openEmbed = $(async (entry: BibEntry) => {
    store.embedUrl = entry.url;
    store.embedTitle = entry.title;
    store.embedMarkdown = null;
    store.embedProvider = null;
    store.embedLoading = true;
    // The Convex action lives in convex/research; the background-research
    // module is the single source of truth for the embed markdown. For now
    // we show the iframe and let the writer click "Open ↗" for the live
    // preview. The background watcher will refresh the panel once data
    // arrives.
    store.embedProvider = "iframe";
    store.embedLoading = false;
  });

  const closeEmbed = $(() => {
    store.embedUrl = null;
    store.embedMarkdown = null;
    store.embedProvider = null;
  });

  const copyAll = $(async () => {
    const text = store.bibliography
      .map((b) => formatCitation(b, store.style))
      .join("\n\n");
    try {
      await navigator.clipboard?.writeText(text);
    } catch {
      /* ignore */
    }
  });

  /* ── AI-enhanced apparatus actions ────────────────────────────── */

  const hasAi = hasConfiguredAiProvider(store.aiSettings);
  const canFlagMissingSources = hasAi && store.flagMissingSources;

  const addToBibliography = $(async (citation: DetectedCitation) => {
    const key = `fmt-${citation.id}`;
    if (store.aiLoading[key]) return;
    store.aiLoading = { ...store.aiLoading, [key]: true };
    try {
      if (hasAi && store.aiSettings) {
        const result = await runClientCitationFormat(
          {
            rawText: citation.text,
            style: store.style,
            context: store.activeFolio?.name,
          },
          store.aiSettings,
        );
        if (result) {
          const all = await mergeBibEntry(
            buildBibEntryFromFormattedCitation(
              citation,
              result,
              store.activeFolio?.id ?? "",
            ),
          );
          store.bibliography = all;
          store.addedCitationIds = {
            ...store.addedCitationIds,
            [citation.id]: true,
          };
          return;
        }
      }
      // Fallback: save raw citation without AI formatting.
      const all = await mergeBibEntry(
        buildBibEntryFromFormattedCitation(
          citation,
          { title: citation.text, url: citation.lookupUrl },
          store.activeFolio?.id ?? "",
        ),
      );
      store.bibliography = all;
      store.addedCitationIds = {
        ...store.addedCitationIds,
        [citation.id]: true,
      };
    } finally {
      store.aiLoading = { ...store.aiLoading, [key]: false };
    }
  });

  const summarizeSourceAi = $(async (entry: BibEntry) => {
    if (!hasAi || !store.aiSettings) return;
    const key = `sum-${entry.id}`;
    store.aiLoading = { ...store.aiLoading, [key]: true };
    try {
      const result = await runClientSourceSummarize(
        { title: entry.title, url: entry.url, author: entry.author },
        store.aiSettings,
      );
      if (result) {
        store.aiSummaries = { ...store.aiSummaries, [entry.id]: result };
      }
    } finally {
      store.aiLoading = { ...store.aiLoading, [key]: false };
    }
  });

  const detectMissingSourcesAi = $(async () => {
    if (!canFlagMissingSources || !store.aiSettings || !store.activeFolio)
      return;
    store.aiScanningMissing = true;
    store.aiMissingSources = null;
    try {
      const html = await loadFolioContentFromIdb(store.activeFolio.id);
      const text = html.replace(/<[^>]+>/g, " ");
      const existing = writerEntries.map((e) => e.title);
      const result = await runClientMissingSourceDetect(
        { draftText: text, existingSources: existing },
        store.aiSettings,
      );
      store.aiMissingSources = result;
    } finally {
      store.aiScanningMissing = false;
    }
  });

  const citedUrls = new Set(
    store.citations
      .map((c) => c.lookupUrl)
      .filter((u): u is string => !!u)
      .map((u) => u.replace(/\/+$/, "")),
  );

  const activeBibliography = store.activeFolio
    ? store.bibliography.filter(
        (b) => b.folioId === store.activeFolio?.id || !b.folioId,
      )
    : store.bibliography;

  const backgroundEntries = activeBibliography.filter(
    (b) => b.provenance === "background",
  );
  const writerEntries = activeBibliography.filter(
    (b) => b.provenance !== "background",
  );

  return (
    <div
      class="min-h-screen bg-[var(--color-paper-soft)] text-[var(--color-ink)]"
      style={{ fontFamily: "var(--font-serif)" }}
    >
      <div class="max-w-5xl mx-auto px-6 py-8">
        <div class="flex items-center justify-between mb-6">
          <div>
            <p
              class="dept-label mb-1"
              style={{ fontFamily: "var(--font-typewriter)" }}
            >
              Twyne
            </p>
            <h1
              style={{
                fontFamily: "var(--font-display)",
                fontWeight: 700,
                fontSize: "1.75rem",
              }}
            >
              The Apparatus
            </h1>
            <p class="text-sm text-[var(--color-ink-light)] mt-1">
              Background agents are reading your draft. Sources they discover
              land here automatically.
            </p>
          </div>
          <Link
            href="/editor/"
            class="btn-paper text-sm"
            style={{ fontFamily: "var(--font-display)" }}
          >
            ← Back to desk
          </Link>
        </div>

        {/* Status card — live snapshot of the background watcher. */}
        <section class="card p-4 mb-6">
          <div class="flex items-center gap-3">
            <span
              class="status-dot"
              style={{
                background:
                  store.research.status === "running"
                    ? "var(--color-mustard)"
                    : store.research.status === "saving"
                      ? "var(--color-cobalt)"
                      : store.research.status === "error"
                        ? "var(--color-vermilion)"
                        : "var(--color-accent-green)",
                animation:
                  store.research.status === "running" ||
                  store.research.status === "saving"
                    ? "pulse 1.6s ease-in-out infinite"
                    : "none",
              }}
              aria-hidden="true"
            />
            <div class="flex-1 min-w-0">
              <p
                class="text-sm text-[var(--color-ink)]"
                style={{ fontFamily: "var(--font-display)", fontWeight: 600 }}
              >
                {store.research.status === "running" &&
                  "Apparatus is searching…"}
                {store.research.status === "saving" &&
                  "Saving discovered sources…"}
                {store.research.status === "error" &&
                  "Apparatus is offline — sources will resume when the connection is back."}
                {store.research.status === "idle" &&
                  (backgroundEntries.length > 0
                    ? `Agents are watching — ${backgroundEntries.length} source${backgroundEntries.length === 1 ? "" : "s"} found so far.`
                    : "Agents are watching your draft. Sources will appear as they are found.")}
              </p>
              {store.research.lastQuery ? (
                <p
                  class="text-[0.7rem] text-[var(--color-ink-muted)] mt-0.5 truncate"
                  style={{ fontFamily: "var(--font-typewriter)" }}
                  title={store.research.lastQuery}
                >
                  last query: {store.research.lastQuery}
                </p>
              ) : (
                <p
                  class="text-[0.7rem] text-[var(--color-ink-muted)] mt-0.5"
                  style={{ fontFamily: "var(--font-typewriter)" }}
                >
                  The Apparatus reads your draft and hunts sources for the
                  claims inside it.
                </p>
              )}
              {store.research.provider && (
                <p
                  class="text-[0.65rem] text-[var(--color-ink-muted)] mt-0.5"
                  style={{ fontFamily: "var(--font-typewriter)" }}
                >
                  provider: {store.research.provider}
                </p>
              )}
            </div>
            <div
              class="text-right"
              style={{ fontFamily: "var(--font-display)" }}
            >
              <p class="text-2xl text-[var(--color-vermilion)] leading-none">
                {backgroundEntries.length}
              </p>
              <p
                class="text-[0.55rem] text-[var(--color-ink-muted)] uppercase tracking-[0.15em] mt-1"
                style={{ fontFamily: "var(--font-typewriter)" }}
              >
                found
              </p>
            </div>
          </div>
          {store.research.error && (
            <p
              class="text-[0.7rem] text-[var(--color-vermilion)] mt-2"
              style={{ fontFamily: "var(--font-typewriter)" }}
            >
              {store.research.error}
            </p>
          )}
        </section>

        <div class="grid lg:grid-cols-[1fr_1.4fr] gap-6">
          {/* Left: sources found by the agents. */}
          <section>
            <h2
              class="text-base font-semibold mb-2"
              style={{ fontFamily: "var(--font-display)" }}
            >
              Found by the agents
            </h2>
            <div class="card">
              {backgroundEntries.length === 0 ? (
                <div class="empty">
                  <p
                    class="text-3xl"
                    style={{
                      fontFamily: "var(--font-display)",
                      color: "var(--color-mustard)",
                    }}
                  >
                    ✦
                  </p>
                  <p class="text-sm mt-2 italic">
                    {store.activeFolio
                      ? "The agents are reading. Sources will appear as they're discovered."
                      : "No active folio to read."}
                  </p>
                </div>
              ) : (
                backgroundEntries.map((entry) => {
                  const isCited = citedUrls.has(entry.url.replace(/\/+$/, ""));
                  return (
                    <div
                      key={entry.id}
                      class="row group slide-in transition-colors hover:bg-[var(--color-paper-soft)] page-turn"
                    >
                      <div class="flex items-start justify-between gap-2">
                        <div class="min-w-0 flex-1">
                          <div class="flex items-center gap-2 mb-1 flex-wrap">
                            <p
                              class="text-sm text-[var(--color-ink)]"
                              style={{
                                fontFamily: "var(--font-display)",
                                fontWeight: 600,
                              }}
                            >
                              {entry.title}
                            </p>
                            <span class="agent-pill">agent</span>
                            {isCited && <span class="cited-pill">cited</span>}
                          </div>
                          <p
                            class="text-[0.65rem] text-[var(--color-ink-muted)] mt-0.5 break-all"
                            style={{ fontFamily: "var(--font-mono)" }}
                          >
                            {entry.url}
                          </p>
                          <p
                            class="text-xs text-[var(--color-ink-light)] mt-1.5 leading-5"
                            style={{ fontFamily: "var(--font-serif)" }}
                          >
                            {formatCitation(entry, store.style)}
                          </p>
                          {entry.target && (
                            <p
                              class="text-[0.6rem] text-[var(--color-ink-muted)] mt-1 italic"
                              style={{ fontFamily: "var(--font-typewriter)" }}
                            >
                              for: “{entry.target.anchor.slice(0, 100)}
                              {entry.target.anchor.length > 100 ? "…" : ""}”
                              <span class="uppercase not-italic ml-1">
                                · {targetKindLabel(entry.target.kind)}
                              </span>
                            </p>
                          )}
                          {entry.backgroundQuery && (
                            <p
                              class="text-[0.6rem] text-[var(--color-ink-muted)] mt-1 italic"
                              style={{ fontFamily: "var(--font-typewriter)" }}
                            >
                              why:{" "}
                              {entry.backgroundQuery.length > 140
                                ? entry.backgroundQuery.slice(0, 140) + "…"
                                : entry.backgroundQuery}
                            </p>
                          )}
                        </div>
                      </div>
                      <div class="mt-2 flex items-center gap-2 flex-wrap opacity-60 group-hover:opacity-100 transition-opacity">
                        <button
                          onClick$={() => openEmbed(entry)}
                          class="text-[0.6rem] tracking-[0.15em] uppercase text-[var(--color-ink-muted)] hover:text-[var(--color-accent)]"
                          style="font-family: var(--font-typewriter);"
                        >
                          ⌖ open
                        </button>
                        <button
                          onClick$={() => dropEntry(entry.id)}
                          class="text-[0.6rem] tracking-[0.15em] uppercase text-[var(--color-ink-muted)] hover:text-[var(--color-vermilion)]"
                          style="font-family: var(--font-typewriter);"
                        >
                          ✕ drop
                        </button>
                      </div>
                    </div>
                  );
                })
              )}
            </div>
          </section>

          {/* Right: writer's bibliography + cross-reference. */}
          <section>
            <div class="flex items-center justify-between mb-2">
              <h2
                class="text-base font-semibold"
                style={{ fontFamily: "var(--font-display)" }}
              >
                Your bibliography
              </h2>
              <div class="flex items-center gap-3">
                <div
                  class="style-toggle"
                  role="group"
                  aria-label="Citation style"
                >
                  {STYLE_OPTIONS.map((s) => (
                    <button
                      key={s.value}
                      onClick$={() => setStyle(s.value)}
                      aria-pressed={store.style === s.value}
                    >
                      {s.label}
                    </button>
                  ))}
                </div>
                <button
                  onClick$={copyAll}
                  class="text-[0.6rem] tracking-[0.15em] uppercase text-[var(--color-ink-muted)] hover:text-[var(--color-accent)]"
                  style="font-family: var(--font-typewriter);"
                >
                  Copy all
                </button>
              </div>
            </div>
            <div class="card mb-4">
              {writerEntries.length === 0 ? (
                <div class="empty">
                  <p
                    class="text-3xl"
                    style={{
                      fontFamily: "var(--font-display)",
                      color: "var(--color-cobalt)",
                    }}
                  >
                    ✎
                  </p>
                  <p class="text-sm mt-2 italic">
                    Nothing you've saved yet. The agents will keep working in
                    the background.
                  </p>
                </div>
              ) : (
                writerEntries.map((entry) => {
                  const isCited = citedUrls.has(entry.url.replace(/\/+$/, ""));
                  const sumKey = `sum-${entry.id}`;
                  const isSummarizing = !!store.aiLoading[sumKey];
                  const summary = store.aiSummaries[entry.id];
                  return (
                    <div
                      key={entry.id}
                      class="row group slide-in transition-colors hover:bg-[var(--color-paper-soft)] page-turn"
                    >
                      <div class="flex items-start justify-between gap-2">
                        <div class="min-w-0 flex-1">
                          <p
                            class="text-sm text-[var(--color-ink)]"
                            style={{
                              fontFamily: "var(--font-display)",
                              fontWeight: 600,
                            }}
                          >
                            {entry.title}
                          </p>
                          <p
                            class="text-[0.65rem] text-[var(--color-ink-muted)] mt-0.5 break-all"
                            style={{ fontFamily: "var(--font-mono)" }}
                          >
                            {entry.url}
                          </p>
                          <p
                            class="text-xs text-[var(--color-ink-light)] mt-1.5 leading-5"
                            style={{ fontFamily: "var(--font-serif)" }}
                          >
                            {formatCitation(entry, store.style)}
                          </p>
                          {isCited && (
                            <span class="cited-pill mt-1.5 inline-block">
                              cited in draft
                            </span>
                          )}
                          {summary && (
                            <div class="mt-2 p-2 bg-[var(--color-paper-soft)] border-l-2 border-[var(--color-mustard)]">
                              <p
                                class="text-[0.6rem] tracking-[0.18em] uppercase text-[var(--color-ink-muted)] mb-1"
                                style={{ fontFamily: "var(--font-typewriter)" }}
                              >
                                ✦ AI summary
                              </p>
                              <p
                                class="text-xs text-[var(--color-ink)] leading-5"
                                style={{ fontFamily: "var(--font-serif)" }}
                              >
                                {summary.summary}
                              </p>
                              {summary.keyClaims.length > 0 && (
                                <ul class="mt-1.5 space-y-0.5">
                                  {summary.keyClaims.map((claim, i) => (
                                    <li
                                      key={i}
                                      class="text-[0.7rem] text-[var(--color-ink-light)] pl-3 relative before:content-['·'] before:absolute before:left-0 before:text-[var(--color-mustard)]"
                                      style={{
                                        fontFamily: "var(--font-serif)",
                                      }}
                                    >
                                      {claim}
                                    </li>
                                  ))}
                                </ul>
                              )}
                            </div>
                          )}
                        </div>
                      </div>
                      <div class="mt-2 flex items-center gap-2 flex-wrap opacity-60 group-hover:opacity-100 transition-opacity">
                        {hasAi && (
                          <button
                            onClick$={() => summarizeSourceAi(entry)}
                            disabled={isSummarizing}
                            class="text-[0.6rem] tracking-[0.15em] uppercase text-[var(--color-mustard)] hover:text-[var(--color-ink)] disabled:opacity-40"
                            style="font-family: var(--font-typewriter);"
                            title="Ask the configured AI to summarize this source."
                          >
                            {isSummarizing ? "summarizing…" : "✦ summarize"}
                          </button>
                        )}
                        <button
                          onClick$={() => dropEntry(entry.id)}
                          class="text-[0.6rem] tracking-[0.15em] uppercase text-[var(--color-ink-muted)] hover:text-[var(--color-vermilion)]"
                          style="font-family: var(--font-typewriter);"
                        >
                          ✕ drop
                        </button>
                      </div>
                    </div>
                  );
                })
              )}
            </div>

            <h2
              class="text-base font-semibold mb-2"
              style={{ fontFamily: "var(--font-display)" }}
            >
              Detected in the manuscript
            </h2>
            <div class="card">
              {store.citations.length === 0 ? (
                <div class="empty">
                  <p class="text-xs italic">
                    {store.activeFolio
                      ? "No DOI / URL / ISBN / author-year citations detected yet — keep writing."
                      : "No active folio to scan."}
                  </p>
                </div>
              ) : (
                store.citations.map((c) => {
                  const fmtKey = `fmt-${c.id}`;
                  const isFormatting = !!store.aiLoading[fmtKey];
                  const isAdded = !!store.addedCitationIds[c.id];
                  return (
                    <div
                      key={c.id}
                      class="row group slide-in transition-colors hover:bg-[var(--color-paper-soft)] page-turn"
                      style={{
                        borderLeft: "3px solid var(--color-paper-3)",
                      }}
                    >
                      <p
                        class="text-xs text-[var(--color-ink)] break-all"
                        style={{ fontFamily: "var(--font-mono)" }}
                      >
                        {c.text}
                      </p>
                      <p
                        class="text-[0.6rem] text-[var(--color-ink-muted)] mt-0.5 flex items-center gap-2 flex-wrap"
                        style={{ fontFamily: "var(--font-typewriter)" }}
                      >
                        <span>{c.type}</span>
                        {c.lookupUrl ? (
                          <>
                            {" · "}
                            <a
                              href={c.lookupUrl}
                              target="_blank"
                              rel="noopener noreferrer"
                              class="hover:text-[var(--color-accent)]"
                            >
                              look up ↗
                            </a>
                          </>
                        ) : null}
                        {isAdded && (
                          <span
                            class="text-[0.55rem] tracking-[0.15em] uppercase px-1 py-0.5"
                            style={{
                              color: "var(--color-accent-green)",
                              border: "1px solid var(--color-accent-green)",
                              borderRadius: "1px",
                            }}
                          >
                            ✓ in bib
                          </span>
                        )}
                        <button
                          onClick$={() => addToBibliography(c)}
                          disabled={isFormatting || isAdded}
                          class="ml-auto text-[0.6rem] tracking-[0.15em] uppercase text-[var(--color-vermilion)] hover:text-[var(--color-vermilion-2)] disabled:opacity-40 disabled:cursor-default"
                          style="font-family: var(--font-typewriter);"
                          title={
                            hasAi
                              ? "Format this citation with AI and add it to your bibliography."
                              : "Add this citation to your bibliography."
                          }
                        >
                          {isFormatting
                            ? "formatting…"
                            : isAdded
                              ? "✓ added"
                              : hasAi
                                ? "✦ add to bib"
                                : "+ add to bib"}
                        </button>
                      </p>
                    </div>
                  );
                })
              )}
            </div>
          </section>
        </div>

        {/* Missing citations — AI scans the draft for claims that need sourcing. */}
        {store.flagMissingSources && (
          <section class="mt-6">
            <div class="flex items-center justify-between mb-2 gap-3 flex-wrap">
              <div>
                <h2
                  class="text-base font-semibold"
                  style={{ fontFamily: "var(--font-display)" }}
                >
                  Missing citations
                </h2>
                <p
                  class="text-[0.7rem] text-[var(--color-ink-muted)] mt-0.5"
                  style={{ fontFamily: "var(--font-typewriter)" }}
                >
                  Ask the configured AI to flag claims in the draft that need a
                  source.
                </p>
              </div>
              {canFlagMissingSources && (
                <button
                  onClick$={detectMissingSourcesAi}
                  disabled={store.aiScanningMissing || !store.activeFolio}
                  class="text-[0.65rem] tracking-[0.15em] uppercase text-[var(--color-mustard)] hover:text-[var(--color-ink)] disabled:opacity-40"
                  style="font-family: var(--font-typewriter);"
                  title="Scan the active draft for claims that need a source."
                >
                  {store.aiScanningMissing
                    ? "scanning…"
                    : store.aiMissingSources
                      ? "✦ re-scan"
                      : "✦ scan for missing citations"}
                </button>
              )}
            </div>
            {!canFlagMissingSources && (
              <p
                class="text-xs text-[var(--color-ink-muted)] italic"
                style={{ fontFamily: "var(--font-serif)" }}
              >
                Configure an AI provider in Settings to enable claim scanning.
              </p>
            )}
            {canFlagMissingSources && store.aiMissingSources && (
              <div class="card">
                {store.aiMissingSources.claims.length === 0 ? (
                  <div class="empty">
                    <p class="text-sm italic">
                      No unsourced claims detected. The draft looks
                      well-attested.
                    </p>
                  </div>
                ) : (
                  store.aiMissingSources.claims.map((claim, i) => (
                    <div key={i} class="row">
                      <p
                        class="text-[0.6rem] tracking-[0.18em] uppercase text-[var(--color-mustard)] mb-1"
                        style={{ fontFamily: "var(--font-typewriter)" }}
                      >
                        claim
                      </p>
                      <p
                        class="text-sm text-[var(--color-ink)] leading-6"
                        style={{ fontFamily: "var(--font-serif)" }}
                      >
                        {claim.claim}
                      </p>
                      <p
                        class="text-[0.7rem] text-[var(--color-ink-light)] mt-1.5"
                        style={{ fontFamily: "var(--font-serif)" }}
                      >
                        {claim.reason}
                      </p>
                      {claim.suggestedQuery && (
                        <p
                          class="text-[0.6rem] text-[var(--color-ink-muted)] mt-1.5 italic"
                          style={{ fontFamily: "var(--font-typewriter)" }}
                        >
                          try searching:{" "}
                          <span class="text-[var(--color-ink)]">
                            {claim.suggestedQuery}
                          </span>
                        </p>
                      )}
                    </div>
                  ))
                )}
              </div>
            )}
          </section>
        )}

        {/* Embed overlay */}
        {store.embedUrl && (
          <div
            class="fixed inset-0 z-50 flex items-center justify-center p-6"
            style="background: rgba(20, 16, 10, 0.55);"
            role="dialog"
            aria-label={`Preview: ${store.embedTitle}`}
            onClick$={closeEmbed}
          >
            <div
              class="bg-[var(--color-paper)] border border-[var(--color-paper-3)] w-full max-w-3xl max-h-[85vh] flex flex-col"
              style="border-radius: 2px;"
              onClick$={(e) => e.stopPropagation()}
            >
              <div class="px-5 py-3 border-b border-[var(--color-paper-3)] flex items-center justify-between gap-3">
                <div class="min-w-0">
                  <p
                    class="text-sm text-[var(--color-ink)] truncate"
                    style={{
                      fontFamily: "var(--font-display)",
                      fontWeight: 600,
                    }}
                  >
                    {store.embedTitle}
                  </p>
                  <p
                    class="text-[0.6rem] text-[var(--color-ink-muted)] truncate"
                    style={{ fontFamily: "var(--font-mono)" }}
                  >
                    {store.embedUrl}
                  </p>
                </div>
                <div class="flex items-center gap-2">
                  <a
                    href={store.embedUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                    class="text-[0.65rem] tracking-[0.15em] uppercase text-[var(--color-ink-muted)] hover:text-[var(--color-accent)]"
                    style="font-family: var(--font-typewriter);"
                  >
                    Open ↗
                  </a>
                  <button
                    onClick$={closeEmbed}
                    class="text-[0.65rem] tracking-[0.15em] uppercase text-[var(--color-ink-muted)] hover:text-[var(--color-vermilion)]"
                    style="font-family: var(--font-typewriter);"
                  >
                    ✕
                  </button>
                </div>
              </div>
              <div class="flex-1 overflow-auto p-5">
                {store.embedLoading ? (
                  <p
                    class="text-xs text-[var(--color-ink-muted)]"
                    style={{ fontFamily: "var(--font-typewriter)" }}
                  >
                    Loading…
                  </p>
                ) : (
                  <iframe
                    src={store.embedUrl}
                    title={store.embedTitle}
                    class="w-full h-[60vh] border border-[var(--color-paper-3)]"
                    sandbox="allow-scripts allow-same-origin allow-popups"
                  />
                )}
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
});

