  try {
    for (const target of fresh) {
      const row = progressItems.find((p) => p.key === targetKey(target));
      if (row) {
        row.status = "searching";
        notify();
      }
      const res = await searchForTarget(target, apparatusSettings);
      if (res) state.lastProvider = res.provider;

      let found = 0;
      if (res) {
        const ranked = rankSourcesForTarget(res.results);
        setStatus("running", "saving");
        found = await persistTarget(target, ranked);
        setStatus("running", "searching");
        if (found > 0) {
          recentTargetKeys.add(targetKey(target));
          state.savedThisSession += found;
        }
      }

      if (row) {
        row.status = found > 0 ? "found" : "missed";
        row.at = Date.now();
        row.count = found;
      }
      logActivity(
        target.kind,
        target.anchor,
        target.query,
        found > 0 ? "found" : "missed",
        found,
      );
      emitSaved(target, found);
    }
  } finally {
    passInFlight = false;
    setStatus("idle", "idle");
  }
}

